parameters.jsCode:
const body = $input.first().json.body;
const required = ['meeting_title', 'raw_notes', 'attendees'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (body.raw_notes.trim().length < 50) return [{ json: { valid: false, error: 'raw_notes too short — need at least 50 characters' } }];

const attendees = Array.isArray(body.attendees)
  ? body.attendees
  : body.attendees.split(',').map(a => a.trim()).filter(Boolean);

const meetingTypes = ['client_meeting', 'internal_team', 'sales_call', 'project_kickoff', 'board_meeting', 'one_on_one', 'discovery_call', 'retrospective', 'planning', 'interview', 'other'];
const meetingType = meetingTypes.includes(body.meeting_type) ? body.meeting_type : 'other';

return [{ json: {
  valid: true,
  meetingTitle: body.meeting_title.trim(),
  meetingType,
  meetingDate: body.meeting_date || new Date().toISOString().split('T')[0],
  rawNotes: body.raw_notes.trim().slice(0, 6000),
  attendees,
  organizer: body.organizer || attendees[0] || '',
  organizerEmail: body.organizer_email || '',
  sendFollowUpEmail: body.send_follow_up_email !== false,
  followUpRecipients: Array.isArray(body.follow_up_recipients)
    ? body.follow_up_recipients
    : (body.follow_up_recipients || '').split(',').map(e => e.trim()).filter(Boolean),
  company: body.company || '',
  projectName: body.project_name || '',
  nextMeetingDate: body.next_meeting_date || '',
  tone: body.tone || 'professional',
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

values.content:
Process these meeting notes and generate follow-up materials.

Meeting: {{ $json.meetingTitle }}
Type: {{ $json.meetingType.replace(/_/g,' ') }}
Date: {{ $json.meetingDate }}
Attendees: {{ $json.attendees.join(', ') }}
Organizer: {{ $json.organizer || 'not specified' }}
Company/project: {{ $json.company || $json.projectName || 'not specified' }}
Next meeting: {{ $json.nextMeetingDate || 'not scheduled' }}
Tone: {{ $json.tone }}

Raw notes:
{{ $json.rawNotes }}

Return this JSON:
{
  "meeting_summary": "2-3 sentence executive summary of what was covered and the overall outcome",
  "decisions_made": [
    {
      "decision": "specific decision that was made",
      "context": "brief rationale or context if relevant",
      "made_by": "person who made the call or 'group'"
    }
  ],
  "action_items": [
    {
      "task": "specific actionable task — starts with a verb",
      "owner": "person responsible — use names from attendees list",
      "due_date": "specific date or 'by next meeting' or 'ASAP'",
      "priority": "high | medium | low",
      "notes": "any relevant detail or dependency"
    }
  ],
  "open_questions": [
    {
      "question": "unresolved question that needs an answer",
      "needs_input_from": "person or team who can answer this"
    }
  ],
  "key_topics_discussed": ["3-5 topics covered — brief phrases, not sentences"],
  "blockers_identified": ["any blockers or risks mentioned — empty if none"],
  "follow_up_email": {
    "subject": "email subject line — specific, not generic",
    "body": "complete follow-up email body — professional, scannable, uses bullet points for action items. Sign off with the organizer's name. Under 300 words."
  },
  "next_meeting_agenda_suggestions": ["2-4 agenda items that logically follow from what was discussed today"]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let processed;
try { processed = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
processed._meta = {
  meetingTitle: input.meetingTitle,
  meetingType: input.meetingType,
  meetingDate: input.meetingDate,
  attendees: input.attendees,
  organizer: input.organizer,
  organizerEmail: input.organizerEmail,
  followUpRecipients: input.followUpRecipients,
  sendFollowUpEmail: input.sendFollowUpEmail,
  company: input.company,
  projectName: input.projectName,
  nextMeetingDate: input.nextMeetingDate,
  replyEmail: input.replyEmail
};
return [{ json: processed }];

const p = $input.first().json;
const m = p._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const priorityColor = {high:'#dc2626', medium:'#d97706', low:'#6b7280'};
const actionRows = (p.action_items||[]).map(a => `
  <tr style="border-bottom:1px solid #f3f4f6">
    <td style="padding:9px 12px;font-size:14px">${esc(a.task)}</td>
    <td style="padding:9px 12px;font-size:13px;font-weight:600;color:#374151">${esc(a.owner||'TBD')}</td>
    <td style="padding:9px 12px;font-size:13px;color:#6b7280">${esc(a.due_date||'')}</td>
    <td style="padding:9px 12px;text-align:center"><span style="background:${priorityColor[a.priority]||'#6b7280'}22;color:${priorityColor[a.priority]||'#6b7280'};font-size:11px;font-weight:700;padding:2px 8px;border-radius:8px">${esc(a.priority||'')}</span></td>
  </tr>`).join('');

const decisionRows = (p.decisions_made||[]).map(d => `
  <div style="padding:9px 0;border-bottom:1px solid #f0fdf4">
    <div style="font-size:14px;font-weight:600;color:#166534">✓ ${esc(d.decision)}</div>
    ${d.context ? `<div style="font-size:13px;color:#6b7280;margin-top:2px">${esc(d.context)}</div>` : ''}
  </div>`).join('');

const openQs = (p.open_questions||[]).map(q => `
  <div style="padding:9px 0;border-bottom:1px solid #f0f9ff">
    <div style="font-size:14px;color:#1e40af">? ${esc(q.question)}</div>
    ${q.needs_input_from ? `<div style="font-size:12px;color:#9ca3af;margin-top:2px">Needs: ${esc(q.needs_input_from)}</div>` : ''}
  </div>`).join('');

const blockerList = (p.blockers_identified||[]).map(b => `<div style="font-size:13px;color:#7f1d1d;padding:5px 0">⚠ ${esc(b)}</div>`).join('');
const topicTags = (p.key_topics_discussed||[]).map(t => `<span style="display:inline-block;background:#f3f4f6;color:#374151;font-size:12px;padding:3px 10px;border-radius:12px;margin:3px 3px 0 0">${esc(t)}</span>`).join('');
const agendaSugg = (p.next_meeting_agenda_suggestions||[]).map((a,i) => `<div style="font-size:13px;color:#374151;padding:5px 0;border-bottom:1px solid #f3f4f6">${i+1}. ${esc(a)}</div>`).join('');

const emailBodyHtml = (p.follow_up_email?.body||'').replace(/\n/g,'<br>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:720px;margin:0 auto">
  <div style="background:#1e293b;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#64748b;margin-bottom:5px">${esc(m.meetingType.replace(/_/g,' '))} · ${esc(m.meetingDate)}</div>
    <div style="font-size:19px;font-weight:700">${esc(m.meetingTitle)}</div>
    <div style="font-size:13px;color:#94a3b8;margin-top:4px">${esc(m.attendees.join(' · '))}</div>
  </div>

  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Summary</div>
    <p style="font-size:15px;line-height:1.7;color:#374151;margin:0 0 10px">${esc(p.meeting_summary)}</p>
    ${topicTags ? `<div style="margin-top:8px">${topicTags}</div>` : ''}
  </div>

  ${decisionRows ? `<div style="background:#f0fdf4;padding:16px 28px;border:1px solid #bbf7d0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:8px">Decisions made</div>
    ${decisionRows}
  </div>` : ''}

  ${actionRows ? `<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Action items</div>
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="font-size:11px;text-transform:uppercase;color:#9ca3af">
        <th style="padding:7px 12px;text-align:left">Task</th>
        <th style="padding:7px 12px;text-align:left">Owner</th>
        <th style="padding:7px 12px;text-align:left">Due</th>
        <th style="padding:7px 12px;text-align:center">Priority</th>
      </tr></thead>
      <tbody>${actionRows}</tbody>
    </table>
  </div>` : ''}

  ${openQs ? `<div style="background:#eff6ff;padding:14px 28px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:8px">Open questions</div>
    ${openQs}
  </div>` : ''}

  ${blockerList ? `<div style="background:#fef2f2;padding:12px 28px;border:1px solid #fecaca">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:6px">Blockers</div>
    ${blockerList}
  </div>` : ''}

  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Follow-up email draft</div>
    <div style="font-size:12px;color:#6b7280;margin-bottom:6px"><strong>Subject:</strong> ${esc(p.follow_up_email?.subject||'')}</div>
    <div style="background:#f8faff;border:1px solid #e0e7ff;border-radius:6px;padding:14px;font-size:14px;line-height:1.75;color:#374151">${emailBodyHtml}</div>
  </div>

  ${agendaSugg ? `<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:7px">Next meeting agenda ideas</div>
    ${agendaSugg}
  </div>` : ''}

  <div style="background:#1e293b;color:#475569;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Meeting Follow-Up · ${esc(m.meetingDate)} · ${esc(m.meetingTitle)}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, followUpEmail: p.follow_up_email, followUpRecipients: m.followUpRecipients, sendFollowUpEmail: m.sendFollowUpEmail, meetingTitle: m.meetingTitle, organizerEmail: m.organizerEmail, processed: p } }];
